async function initSupabase(){
 if(!supabaseClient){$('authStatus').textContent='Account service could not load.';return}
 const {data:{session}}=await supabaseClient.auth.getSession();
 await applyAuthSession(session);
 supabaseClient.auth.onAuthStateChange((event,session)=>{
   if(event==='PASSWORD_RECOVERY') setTimeout(()=>showPasswordRecovery(),0);
   setTimeout(()=>applyAuthSession(session),0)
 });
}
function setAuthStatus(message,isError=false){const el=$('authStatus');if(!el)return;el.innerHTML=isError?`<span class="error">${escapeHtml(message)}</span>`:escapeHtml(message||'')}
async function applyAuthSession(session){
 currentUser=session?.user||null;
 $('authSignedOut')?.classList.toggle('hidden',!!currentUser);$('signOut')?.classList.toggle('hidden',!currentUser);$('profileTools')?.classList.toggle('hidden',!currentUser);$('basicsProfileActions')?.classList.toggle('hidden',!currentUser);
 const badge=$('accountBadge');if(badge){badge.textContent=currentUser?t().cloud:t().notSigned;badge.classList.toggle('online',!!currentUser)}
 if(currentUser){setAuthStatus('');updateSetupNav();await Promise.all([loadCloudProfiles(),loadCloudStories(),loadStoryCredits()]);await loadCurrentChildPhoto();if(!window.__moonbeamCheckoutHandled){window.__moonbeamCheckoutHandled=true;await handleCheckoutReturn()}if(!$('productApp')?.classList.contains('hidden')&&setupPageIndex===0&&$('passwordRecovery')?.classList.contains('hidden'))goSetupPage(1,true)}else{updateSetupNav();cloudProfiles=[];activeProfileId=null;cloudStories=[];renderProfileSelect();renderLibrary();renderStoryCredits(null);await loadCurrentChildPhoto()}
}

function showPasswordRecovery(){
 const panel=$('passwordRecovery');if(!panel)return;
 panel.classList.remove('hidden');
 if(isPhonePortrait())goSetupPage(0);
 if($('recoveryStatus'))$('recoveryStatus').textContent='Reset link verified. Choose your new password.';
}
async function sendPasswordReset(){
 if(!supabaseClient){setAuthStatus('Account service could not load.',true);return}
 const email=$('authEmail')?.value.trim();
 if(!email){setAuthStatus('Enter your email address first, then tap Forgot password.',true);$('authEmail')?.focus();return}
 setAuthStatus('Sending password reset email…');
 const redirectTo=location.origin + location.pathname;
 const {error}=await supabaseClient.auth.resetPasswordForEmail(email,{redirectTo});
 if(error){setAuthStatus(error.message,true);return}
 setAuthStatus('Password reset email sent. Check your inbox and open the link to choose a new password.');
}
async function saveNewPassword(){
 if(!supabaseClient)return;
 const password=$('newPassword')?.value||'',confirm=$('confirmNewPassword')?.value||'';
 const status=$('recoveryStatus');
 if(password.length<6){if(status)status.innerHTML='<span class="error">Use a password of at least 6 characters.</span>';return}
 if(password!==confirm){if(status)status.innerHTML='<span class="error">The two passwords do not match.</span>';return}
 if(status)status.textContent='Saving your new password…';
 const {error}=await supabaseClient.auth.updateUser({password});
 if(error){if(status)status.innerHTML=`<span class="error">${escapeHtml(error.message)}</span>`;return}
 if(status)status.textContent='Password changed successfully. You are signed in.';
 if($('newPassword'))$('newPassword').value='';if($('confirmNewPassword'))$('confirmNewPassword').value='';
 setTimeout(()=>{$('passwordRecovery')?.classList.add('hidden');setAuthStatus('Password changed successfully.');history.replaceState({},document.title,location.pathname)},1300);
}

async function signUpParent(){
 const email=$('authEmail').value.trim(),password=$('authPassword').value;
 if(!email||password.length<6){setAuthStatus('Enter your email and a password of at least 6 characters.',true);return}
 setAuthStatus('Creating your account…');
 const {data,error}=await supabaseClient.auth.signUp({email,password,options:{emailRedirectTo:location.origin}});
 if(error){setAuthStatus(error.message,true);return}
 if(data.session)setAuthStatus('Account created and signed in.');else setAuthStatus('Account created. Check your email to confirm it, then return here and sign in.');
}
async function signInParent(){
 const email=$('authEmail').value.trim(),password=$('authPassword').value;
 if(!email||!password){setAuthStatus('Enter your email and password.',true);return}
 setAuthStatus('Signing in…');const {error}=await supabaseClient.auth.signInWithPassword({email,password});if(error)setAuthStatus(error.message,true);else setAuthStatus('');
}
async function signOutParent(){await supabaseClient.auth.signOut();setAuthStatus('Signed out.')}
function formChild(){return{name:$('name').value.trim(),age:Number($('age').value),interests:$('interests').value.trim(),dislikes:$('dislikes').value.trim()}}
function renderProfileSelect(){
 const sel=$('profileSelect');if(!sel)return;
 const selected=activeProfileId||'';
 const profileOptions=cloudProfiles.map(p=>`<option value="${escapeHtml(p.id)}">${escapeHtml(p.name)}${p.age?` — ${p.age}`:''}</option>`).join('');
 const active=cloudProfiles.find(p=>p.id===activeProfileId);
 const deleteOption=active?`<option disabled>──────────</option><option value="__delete_profile__">${escapeHtml(t().deleteProfile || 'Delete profile')} ${escapeHtml(active.name)}…</option>`:'';
 sel.innerHTML='<option value="">New child</option>'+profileOptions+deleteOption;sel.value=selected;
}
async function selectCloudProfile(){
 const sel=$('profileSelect');
 if(sel?.value==='__delete_profile__'){sel.value=activeProfileId||'';await deleteChildProfile();return}
 activeProfileId=sel?.value||null;$('profileStatus').textContent='';
 if(!activeProfileId){$('name').value='';$('age').value=7;$('interests').value='';$('dislikes').value='';await loadCurrentChildPhoto();return}
 const p=cloudProfiles.find(x=>x.id===activeProfileId);if(!p)return;$('name').value=p.name||'';$('age').value=p.age||7;$('interests').value=p.interests||'';$('dislikes').value=p.dislikes||'';await loadCurrentChildPhoto();
}
async function loadCloudProfiles(){
 if(!currentUser)return;const {data,error}=await supabaseClient.from('child_profiles').select('id,name,age,interests,dislikes,created_at').order('created_at',{ascending:true});if(error){$('profileStatus').innerHTML=`<span class="error">${escapeHtml(error.message)}</span>`;return}cloudProfiles=data||[];if(activeProfileId&&!cloudProfiles.some(p=>p.id===activeProfileId))activeProfileId=null;renderProfileSelect()
}
async function saveChildProfile(){
 if(!currentUser)return;const c=formChild();if(!c.name){$('profileStatus').textContent=t().errorName;return}if(c.age<3||c.age>12){$('profileStatus').textContent=t().errorAge;return}$('profileStatus').textContent='Saving…';
 let result;if(activeProfileId)result=await supabaseClient.from('child_profiles').update(c).eq('id',activeProfileId).select().single();else result=await supabaseClient.from('child_profiles').insert({...c,parent_id:currentUser.id}).select().single();
 if(result.error){$('profileStatus').innerHTML=`<span class="error">${escapeHtml(result.error.message)}</span>`;if($('profileStatusBasics'))$('profileStatusBasics').innerHTML=`<span class="error">${escapeHtml(result.error.message)}</span>`;return}const wasNew=!activeProfileId;const draftKey=currentPhotoKey(null);activeProfileId=result.data.id;if(wasNew&&currentChildPhoto){await childPhotoPut(currentPhotoKey(activeProfileId),currentChildPhoto);await childPhotoDelete(draftKey)}await loadCloudProfiles();$('profileSelect').value=activeProfileId;renderProfileSelect();$('profileStatus').textContent='Child profile saved.';if($('profileStatusBasics'))$('profileStatusBasics').textContent='Child profile saved.';
}
async function ensureCloudProfile(child){
 if(!currentUser)return null;if(activeProfileId&&cloudProfiles.some(p=>p.id===activeProfileId)){const {error}=await supabaseClient.from('child_profiles').update({name:child.name,age:child.age,interests:child.interests,dislikes:child.dislikes}).eq('id',activeProfileId);if(!error)return activeProfileId}
 const draftKey=currentPhotoKey(null);const {data,error}=await supabaseClient.from('child_profiles').insert({parent_id:currentUser.id,name:child.name,age:child.age,interests:child.interests,dislikes:child.dislikes}).select('id').single();if(error)throw error;activeProfileId=data.id;if(currentChildPhoto){await childPhotoPut(currentPhotoKey(activeProfileId),currentChildPhoto);await childPhotoDelete(draftKey)}await loadCloudProfiles();return data.id
}
async function deleteChildProfile(){
 if(!currentUser||!activeProfileId)return;const doomed=cloudProfiles.find(p=>p.id===activeProfileId);if(!confirm(`Delete ${doomed?.name||'this child'}’s profile? Saved stories will remain in your library.`))return;const oldPhotoKey=currentPhotoKey(activeProfileId);const {error}=await supabaseClient.from('child_profiles').delete().eq('id',activeProfileId);if(error){$('profileStatus').innerHTML=`<span class="error">${escapeHtml(error.message)}</span>`;return}await childPhotoDelete(oldPhotoKey);activeProfileId=null;await loadCloudProfiles();await selectCloudProfile();$('profileStatus').textContent='Profile deleted.'
}
async function loadCloudStories(){
 if(!currentUser)return;const {data,error}=await supabaseClient.from('saved_stories').select('*').order('created_at',{ascending:false}).limit(50);if(error){console.error(error);return}cloudStories=(data||[]).map(row=>{const profile=cloudProfiles.find(p=>p.id===row.child_id);return{id:row.id,title:row.title,child:{...(profile||{name:'',age:7,interests:'',dislikes:''}),profileId:row.child_id},story:{title:row.title,opening:row.opening||'',character_bible:row.character_bible||'',pages:Array.isArray(row.pages)?row.pages:[],closing:row.closing||''},language:row.language,length:row.length,tone:row.tone,values:row.values,generationRunId:row.generation_run_id||null,translations:(row.translations&&typeof row.translations==='object')?row.translations:{},savedAssets:(row.saved_assets&&typeof row.saved_assets==='object')?row.saved_assets:{},at:row.created_at}});renderLibrary()
}
function dataUrlToBlob(dataUrl){const m=String(dataUrl||'').match(/^data:([^;]+);base64,(.+)$/);if(!m)throw new Error('A finished illustration is missing.');const binary=atob(m[2]),bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);return new Blob([bytes],{type:m[1]||'image/webp'})}
async function finishedImageForSave(index){const book=currentBook;if(!book)throw new Error('No story is open.');const key=illustrationKey(book,index,getIllustrationPrompt(index));let image=illustrationCache.get(key)||await persistentImageGet(key);if(!image)image=await requestIllustration(key,getIllustrationPrompt(index),`Premium children's storybook illustration. Consistent recurring characters: ${book.character_bible||'Keep the main child character visually consistent across the book.'}`,false,book.child?.referencePhoto||null);return image}
async function finishedCoverForSave(){const book=currentBook;if(!book)throw new Error('No story is open.');const key=coverKey(book);let image=illustrationCache.get(key)||await persistentImageGet(key);if(!image)image=await requestIllustration(key,getCoverPrompt(book),`Premium children's storybook cover artwork. Consistent recurring characters: ${book.character_bible||'Keep the main child character visually consistent across the book.'}`,false,book.child?.referencePhoto||null);return image}
async function uploadSavedBookArt(storyId){if(!currentUser||!currentBook)throw new Error('Sign in to save the complete book.');const total=currentBook.pages.length+2,assets={version:1,cover:null,pages:[]},base=`${currentUser.id}/${storyId}`;const cover=await finishedCoverForSave(),coverPath=`${base}/cover.webp`;let r=await supabaseClient.storage.from('saved-story-art').upload(coverPath,dataUrlToBlob(cover),{contentType:'image/webp',upsert:true,cacheControl:'31536000'});if(r.error)throw r.error;assets.cover=coverPath;for(let i=0;i<total;i++){const image=await finishedImageForSave(i),path=`${base}/page-${i}.webp`;r=await supabaseClient.storage.from('saved-story-art').upload(path,dataUrlToBlob(image),{contentType:'image/webp',upsert:true,cacheControl:'31536000'});if(r.error)throw r.error;assets.pages.push(path)}return assets}
